def normalize_name(s):
    return s.strip()


def slugify(value):
    """Turn a title into a URL-friendly slug."""
    value = value.lower().strip()
    chars = []
    for ch in value:
        if ch.isalnum():
            chars.append(ch)
        elif ch in (" ", "-", "_"):
            chars.append("-")
    slug = "".join(chars)
    while "--" in slug:
        slug = slug.replace("--", "-")
    return slug.strip("-")


def truncate(text, limit=80):
    """Shorten text to limit characters, adding an ellipsis when cut."""
    if len(text) <= limit:
        return text
    return text[: limit - 3].rstrip() + "..."


def collapse_whitespace(text):
    return " ".join(text.split())
